  window.__goboLevels=Array.from({length:80},(_,i)=>({id:i+1,difficulty:i<4?1:(i<20?2:3)}));
  function open(){document.body.classList.add('gobo-feature-open');renderModal();}
  function close(){document.body.classList.remove('gobo-feature-open');const m=$('#gobo-modal');if(m)m.remove();}
  function render(){}
  function claim(id,reward){const q=resetInfo();if(q.claimed[id])return; q.claimed[id]=true;saveQ(q);addGems(reward,'Quest abgeschlossen');}
